CREATE OR REPLACE FUNCTION public.planning_external_portal_upgrade(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; t text; BEGIN PERFORM 1 FROM public.planning_external_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND expires_at>now() FOR UPDATE; e:=public.planning_external_identity(_token); IF e.id IS NULL OR e.external_person_id IS NULL THEN RAISE EXCEPTION 'Logg inn på nytt' USING ERRCODE='42501'; END IF; t:=public.planning_external_portal_mint(e.external_person_id); UPDATE public.planning_external_sessions SET expires_at=now() WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex'); RETURN jsonb_build_object('portal_token',t); END $$;
CREATE FUNCTION public.planning_external_invalidate_credentials() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='revoked' OR NEW.deleted_at IS NOT NULL THEN UPDATE public.planning_external_login_links SET used_at=coalesce(used_at,now()) WHERE participant_id=NEW.id; UPDATE public.planning_external_sessions SET expires_at=least(expires_at,now()) WHERE participant_id=NEW.id; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.planning_external_invalidate_credentials() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER planning_external_invalidate_credentials AFTER UPDATE OF status,deleted_at ON public.planning_external_participants FOR EACH ROW EXECUTE FUNCTION public.planning_external_invalidate_credentials();
CREATE INDEX planning_external_portal_expiry ON public.planning_external_portal_sessions(person_id,expires_at);
CREATE INDEX planning_external_login_person_rate ON public.planning_external_login_links(participant_id,created_at);
CREATE INDEX planning_external_person_projects ON public.planning_external_participants(external_person_id,planning_project_id) WHERE status='active' AND deleted_at IS NULL;